// Le o "Results: N" da primeira pagina e devolve um item por pagina a raspar.
// Cada item vira uma requisicao no HTTP Request seguinte.
const cfg = $('Configuracao').first().json;
const html = $input.first().json.data;

const m = html.match(/Results:\s*([\d,.]+)/);
const total = m ? parseInt(m[1].replace(/[,.]/g, ''), 10) : 0;

const POR_PAGINA = 25;
let paginas = Math.max(1, Math.ceil(total / POR_PAGINA));
if (cfg.max_pages) paginas = Math.min(paginas, cfg.max_pages);

const out = [];
for (let p = 1; p <= paginas; p++) {
  out.push({ json: { ...cfg, currentpage: p, total_results: total, paginas } });
}
return out;

// ---- parser do Char Bazaar (espelha tibia_bazaar_scraper.py) ----
function decode(s) {
  return s.replace(/&#160;|&nbsp;/g, ' ').replace(/&amp;/g, '&')
          .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
          .replace(/&lt;/g, '<').replace(/&gt;/g, '>');
}

function stripTags(s) {
  return decode(s.replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
}

function parseAuctions(html) {
  const out = [];

  // Fatia o HTML nos limites de <div class="Auction">.
  const starts = [];
  const re = /<div class="Auction"\s*>/g;
  let m;
  while ((m = re.exec(html)) !== null) starts.push(m.index);

  for (let i = 0; i < starts.length; i++) {
    const fim = i + 1 < starts.length ? starts[i + 1] : html.length;
    const block = html.slice(starts[i], fim);

    const idM = block.match(/auctionid=(\d+)/);
    if (!idM) continue;
    const auction_id = parseInt(idM[1], 10);

    const nameM = block.match(/<div class="AuctionCharacterName"\s*>\s*<a[^>]*>([^<]*)<\/a>/);
    if (!nameM) continue;
    const name = decode(nameM[1]).trim();

    // O cabecalho e tudo que vem antes do AuctionBody, sem as tags.
    // O mundo vem dentro de um <a>, entao tem que tirar as tags antes do regex.
    const headEnd = block.indexOf('<div class="AuctionBody"');
    const headerText = stripTags(block.slice(0, headEnd === -1 ? block.length : headEnd));
    const grab = (rx) => { const g = headerText.match(rx); return g ? g[1].trim() : null; };

    const level = grab(/Level:\s*(\d+)/);
    const vocation = grab(/Vocation:\s*(.+?)\s*\|/);
    const sex = grab(/\|\s*(Male|Female)\s*\|/);
    const world = grab(/World:\s*(\w+)/);

    // Datas e lance vem como pares rotulo/valor, nao como texto corrido:
    // pra cada rotulo, vale o primeiro valor que aparecer depois dele.
    const labels = [], values = [];
    let r = /<div class="ShortAuctionDataLabel"\s*>(.*?)<\/div>/g;
    while ((m = r.exec(block)) !== null) labels.push({ pos: m.index, text: stripTags(m[1]) });
    r = /<div class="ShortAuctionDataValue"\s*>(.*?)<\/div>/g;
    while ((m = r.exec(block)) !== null) values.push({ pos: m.index, text: stripTags(m[1]) });

    const short = {};
    for (const lb of labels) {
      const v = values.find((x) => x.pos > lb.pos);
      if (v) short[lb.text.replace(/:$/, '')] = v.text;
    }

    let bid = null, bid_type = null;
    for (const label of ['Current Bid', 'Minimum Bid']) {
      if (short[label]) {
        bid_type = label;
        bid = parseInt(short[label].replace(/[^\d]/g, ''), 10);
        break;
      }
    }

    const highlights = [];
    r = /<div class="Entry"[^>]*>(.*?)<\/div>/g;
    while ((m = r.exec(block)) !== null) {
      const t = stripTags(m[1]);
      if (t) highlights.push(t);
    }

    // O href da pagina traz "&currentpage=", que vira a entidade &curren; e
    // corrompe a URL. Remontar pelo id evita isso.
    out.push({
      auction_id,
      name,
      level: level ? parseInt(level, 10) : null,
      vocation,
      sex,
      world,
      bid,
      bid_type,
      auction_end: short['Auction End'] || null,
      url: 'https://www.tibia.com/charactertrade/?subtopic=currentcharactertrades'
           + '&page=details&auctionid=' + auction_id,
      highlights,
    });
  }

  return out;
}

// ---- junta todas as paginas recebidas ----
const cfg = $('Configuracao').first().json;

let todos = [];
for (const item of $input.all()) {
  const html = item.json.data;
  if (typeof html === 'string') todos = todos.concat(parseAuctions(html));
}

// Leiloes terminam a todo momento, entao a paginacao pode repetir um item
// entre uma requisicao e outra. Mantem so a primeira ocorrencia de cada id.
const vistos = new Set();
todos = todos.filter((a) => {
  if (vistos.has(a.auction_id)) return false;
  vistos.add(a.auction_id);
  return true;
});

if (cfg.limit) todos = todos.slice(0, cfg.limit);

return todos.map((a) => ({ json: a }));
